    hecke: { level: 4, reason: "Neuformen zu Γ<sub>0</sub>(N) und ihre L-Funktionen setzen Hecke-Theorie voraus." },
    waldspurger: { level: 5, reason: "Modulformen halbganzen Gewichts, Shimura-Korrespondenz und Werte getwisteter L-Funktionen sind Forschungsniveau." },
