    fermat: { level: 1, reason: "x<sup>n</sup> + y<sup>n</sup> = z<sup>n</sup> hat für n ≥ 3 keine Lösung in positiven ganzen Zahlen; das ist Schulstoff." },

    // ---------------------------------------------------------------- Elliptic curves and BSD
