    hasse: { level: 2, reason: "Eine Weierstraß-Gleichung und das Zählen ihrer Lösungen modulo p genügen." },
    satotate: { level: 2, reason: "Die Zahlen a<sub>p</sub>, Winkel und Gleichverteilung bezüglich einer Dichte genügen; „ohne komplexe Multiplikation“ heißt, dass die j-Invariante keinen der 13 bekannten Ausnahmewerte hat." },
    lellfort: { level: 3, reason: "Analytische Fortsetzung des Euler-Produkts aus den Zahlen a<sub>p</sub> wird gebraucht." },
