    goldfeld: { level: 3, reason: "Quadratische Twists, analytischer Rang und Grenzwerte von Anteilen werden gebraucht." },
    bsdselmer: { level: 5, reason: "p<sup>∞</sup>-Selmer-Gruppen und ihr Korang sind Forschungsniveau." },
    ellmatroid: { level: 5, reason: "Realisierungsräume von Matroiden und die Modulkurve X<sub>1</sub>(n) über ℤ[1/n] sind Forschungsniveau." },
    matroidmazur: { level: 2, version: "Für Primzahlen p ≥ 11 hat keine elliptische Kurve über ℚ einen rationalen Punkt der Ordnung p (nach Baker gleichwertig).", reason: "Die eigene Fassung braucht Matroide und ihre Darstellbarkeit (Stufe 3); es zählt der gleichwertige Primzahlfall des Satzes von Mazur." },

