    baker: { level: 2, reason: "Algebraische Zahlen, Logarithmen und eine Abschätzung nach unten genügen." },
    sunit: { level: 1, version: "Ist S eine feste endliche Menge von Primzahlen, so gibt es nur endlich viele teilerfremde a + b = c, bei denen alle Primteiler von a, b und c in S liegen.", reason: "Primfaktoren und Teilerfremdheit sind Schulstoff." },
    stewartyu: { level: 1, reason: "Radikal und Logarithmus genügen." },
    darmongranville: { level: 1, reason: "Ganzzahlige Lösungen von x<sup>a</sup> + y<sup>b</sup> = z<sup>c</sup> und Brüche sind Schulstoff." },
    abc: { level: 1, version: "Für jedes ε > 0 gibt es nur endlich viele teilerfremde a + b = c mit c > rad(abc)<sup>1+ε</sup>; rad(n) ist das Produkt der verschiedenen Primteiler von n.", reason: "Primteiler, Produkt und Potenz sind Schulstoff." },
    szpiro: { level: 3, reason: "Minimale Diskriminante und Führer einer elliptischen Kurve werden gebraucht." },
    modszpiro: { level: 1, version: "Gleichwertig zur abc-Vermutung (Oesterlé 1988): Für jedes ε > 0 gibt es nur endlich viele teilerfremde a + b = c mit c > rad(abc)<sup>1+ε</sup>.", reason: "Die eigene Fassung braucht die Invarianten c<sub>4</sub>, c<sub>6</sub> und den Führer (Stufe 3); es zählt die gleichwertige abc-Vermutung." },
    fermatcatalan: { level: 1, reason: "Ganzzahlige Lösungen von x<sup>a</sup> + y<sup>b</sup> = z<sup>c</sup> sind Schulstoff." },

